def _exponent(
    data: jnp.ndarray,
    exponent: Union[float, jnp.ndarray] = 1.5,
) -> jnp.ndarray:
  """Calculates the exponent value of a given array.

  Args:
    data: Input array.
    exponent: exponent effect of the exponent function. Default is 1.5.

  Returns:
    The exponent output of the input array.
  """
  return jnp.power(data, exponent)


